toolArgs.file_text:
@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Total="allTasks.Count"
                ToDo="GetTasksByStatus("To Do").Count"
                InProgress="GetTasksByStatus("In Progress").Count"
                DoneCount="GetTasksByStatus("Done").Count"
                Overdue="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Status="To Do"
                      Tasks="GetFilteredTasksByStatus("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn ColumnName="In Progress"
                      Status="In Progress"
                      Tasks="GetFilteredTasksByStatus("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn ColumnName="Done"
                      Status="Done"
                      Tasks="GetFilteredTasksByStatus("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = "";
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksByStatus(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksByStatus(string status) =>
        allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(searchTerm) ||
                        t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string term)
    {
        searchTerm = term;
    }

    private async Task HandleMoveTask((TaskItem Task, string Direction) move)
    {
        var currentIndex = Array.IndexOf(Statuses, move.Task.Status);
        var newIndex = move.Direction == "left" ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= Statuses.Length) return;

        var newStatus = Statuses[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(move.Task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == move.Task.Id);
            if (index >= 0)
            {
                allTasks[index] = move.Task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate, string Status) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            allTasks.Add(newTask with { Status = data.Status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}

